export const Suit = Object.freeze({
  Clubs: Symbol('clubs'),
  Diamonds: Symbol('diamonds'),
  Hearts: Symbol('hearts'),
  Spades: Symbol('spades'),
});

// boundary validation is the only way in:
export function parseSuit(raw) {
  const hit = Object.values(Suit).find(v => v.description === raw);
  if (!hit) throw new Error(`unknown suit: ${raw}`);
  return hit;
}
